diff --git a/src/ui/glyph_cache.h b/src/ui/glyph_cache.h
new file mode 100644
index 0000000..6cbc1ca
--- /dev/null
+++ b/src/ui/glyph_cache.h
@@ -0,0 +1,59 @@
+#ifndef GLYPH_CACHE_H
+#define GLYPH_CACHE_H
+
+#include <stdbool.h>
+#include <stdint.h>
+
+// Glyphs rasterise on first use at the exact pixel size into RGBA8 atlas pages: white, with coverage in alpha.
+// When every page is full, the least recently used one is cleared; one used this frame is never cleared.
+#define VD_GLYPH_ATLAS_PAGE_SIZE 1024
+#define VD_GLYPH_ATLAS_PAGE_BYTES (VD_GLYPH_ATLAS_PAGE_SIZE * VD_GLYPH_ATLAS_PAGE_SIZE * 4)
+#define VD_GLYPH_ATLAS_PAGE_MAX 4
+
+#define VD_UTF8_REPLACEMENT 0xfffd
+
+typedef struct VdGlyphFont VdGlyphFont;
+
+typedef struct {
+    float ascent;
+    // Below the baseline, positive.
+    float descent;
+    float line_gap;
+} VdGlyphFontMetrics;
+
+typedef struct {
+    // -1 when the glyph has no pixels, like a space, or found no room this frame.
+    int page;
+    int x, y, width, height;
+    // From the pen position on the baseline to the bitmap's top-left corner.
+    int offset_x, offset_y;
+    float advance;
+} VdGlyph;
+
+typedef struct {
+    int pages;
+    int glyphs;
+    int rasterised;
+} VdGlyphCacheStats;
+
+// TrueType or OpenType; NULL when the file is missing or not a font.
+VdGlyphFont *glyph_font_load(const char *path);
+// Call glyph_cache_reset first: cached glyphs are keyed by font.
+void glyph_font_free(VdGlyphFont *font);
+VdGlyphFontMetrics glyph_font_metrics(const VdGlyphFont *font, int size);
+
+// Codepoints a font lacks come from the fallback; ones neither has draw the requested font's missing-glyph box.
+void glyph_cache_set_fallback(const VdGlyphFont *font);
+VdGlyph glyph_cache_get(const VdGlyphFont *font, int size, uint32_t codepoint);
+void glyph_cache_begin_frame(void);
+// Drops every glyph and page.
+void glyph_cache_reset(void);
+// The page's pixels if they changed since the last call, else NULL.
+const unsigned char *glyph_cache_take_dirty_page(int page);
+VdGlyphCacheStats glyph_cache_stats(void);
+
+// Decodes the codepoint at text, which must not be at its terminator, and sets length to the bytes it used.
+// Malformed UTF-8 decodes one byte at a time as VD_UTF8_REPLACEMENT.
+uint32_t vd_utf8_next(const char *text, int *length);
+
+#endif /* GLYPH_CACHE_H */

diff --git a/src/ui/glyph_cache.c b/src/ui/glyph_cache.c
new file mode 100644
index 0000000..75797d7
--- /dev/null
+++ b/src/ui/glyph_cache.c
@@ -0,0 +1,290 @@
+#include "glyph_cache.h"
+
+#include <stdlib.h>
+#include <string.h>
+#include "core/util.h"
+#include "stb_ds.h"
+
+// raylib compiles its own static copy; this one is ours, so rasterising does not depend on raylib internals.
+#define STBTT_STATIC
+#define STB_TRUETYPE_IMPLEMENTATION
+#include "stb_truetype.h"
+
+#define GLYPH_PADDING 1
+
+struct VdGlyphFont {
+    char *data;
+    stbtt_fontinfo info;
+};
+
+typedef struct {
+    const VdGlyphFont *font;
+    int size;
+    uint32_t codepoint;
+} GlyphKey;
+
+typedef struct {
+    GlyphKey key;
+    VdGlyph value;
+} GlyphEntry;
+
+// Shelf packing: glyphs fill a row left to right, and a row is as tall as its tallest glyph.
+typedef struct {
+    unsigned char *pixels;
+    bool dirty;
+    unsigned last_used;
+    int cursor_x, cursor_y, row_height;
+} AtlasPage;
+
+static GlyphEntry *g_glyphs = NULL;
+static AtlasPage g_pages[VD_GLYPH_ATLAS_PAGE_MAX];
+static int g_page_count = 0;
+static int g_current_page = -1;
+static unsigned g_frame = 1;
+static int g_rasterised = 0;
+static const VdGlyphFont *g_fallback = NULL;
+
+static uint32_t read_u32(const unsigned char *bytes)
+{
+    return (uint32_t)bytes[0] << 24 | (uint32_t)bytes[1] << 16 | (uint32_t)bytes[2] << 8 | bytes[3];
+}
+
+// stb_truetype trusts the file, so reject one whose table directory points outside it. Tables are not checked.
+static bool tables_in_bounds(const unsigned char *data, size_t length)
+{
+    if (!data || length < 12) return false;
+    size_t count = (size_t)data[4] << 8 | data[5];
+    if (12 + count * 16 > length) return false;
+    for (size_t i = 0; i < count; i++) {
+        const unsigned char *record = data + 12 + i * 16;
+        size_t offset = read_u32(record + 8);
+        size_t size = read_u32(record + 12);
+        if (offset > length || size > length - offset) return false;
+    }
+    return true;
+}
+
+VdGlyphFont *glyph_font_load(const char *path)
+{
+    VdGlyphFont *font = calloc(1, sizeof(*font));
+    if (!font) return NULL;
+    size_t length = 0;
+    font->data = vd_read_file(path, &length);
+    const unsigned char *data = (const unsigned char *)font->data;
+    if (!tables_in_bounds(data, length) || !stbtt_InitFont(&font->info, data, 0)) {
+        free(font->data);
+        free(font);
+        return NULL;
+    }
+    return font;
+}
+
+void glyph_font_free(VdGlyphFont *font)
+{
+    if (!font) return;
+    if (g_fallback == font) g_fallback = NULL;
+    free(font->data);
+    free(font);
+}
+
+VdGlyphFontMetrics glyph_font_metrics(const VdGlyphFont *font, int size)
+{
+    float scale = stbtt_ScaleForPixelHeight(&font->info, (float)size);
+    int ascent = 0, descent = 0, line_gap = 0;
+    stbtt_GetFontVMetrics(&font->info, &ascent, &descent, &line_gap);
+    return (VdGlyphFontMetrics){ascent * scale, -descent * scale, line_gap * scale};
+}
+
+void glyph_cache_set_fallback(const VdGlyphFont *font)
+{
+    g_fallback = font;
+}
+
+static bool page_place(AtlasPage *page, int width, int height, int *x, int *y)
+{
+    if (page->cursor_x + width > VD_GLYPH_ATLAS_PAGE_SIZE) {
+        page->cursor_x = 0;
+        page->cursor_y += page->row_height + GLYPH_PADDING;
+        page->row_height = 0;
+    }
+    if (page->cursor_y + height > VD_GLYPH_ATLAS_PAGE_SIZE) return false;
+    *x = page->cursor_x;
+    *y = page->cursor_y;
+    page->cursor_x += width + GLYPH_PADDING;
+    if (height > page->row_height) page->row_height = height;
+    return true;
+}
+
+static void clear_page(int index)
+{
+    AtlasPage *page = &g_pages[index];
+    memset(page->pixels, 0, VD_GLYPH_ATLAS_PAGE_BYTES);
+    page->dirty = true;
+    page->cursor_x = page->cursor_y = page->row_height = 0;
+    // hmdel moves the last entry into the deleted slot, which a backwards walk has already visited.
+    for (ptrdiff_t i = hmlen(g_glyphs) - 1; i >= 0; i--) {
+        if (g_glyphs[i].value.page != index) continue;
+        GlyphKey key = g_glyphs[i].key;
+        hmdel(g_glyphs, key);
+    }
+}
+
+// The page that now holds a width x height rect at (x, y), or -1 when no page can take it this frame.
+static int atlas_allocate(int width, int height, int *x, int *y)
+{
+    if (width > VD_GLYPH_ATLAS_PAGE_SIZE || height > VD_GLYPH_ATLAS_PAGE_SIZE) return -1;
+    if (g_current_page >= 0 && page_place(&g_pages[g_current_page], width, height, x, y)) return g_current_page;
+
+    int index;
+    if (g_page_count < VD_GLYPH_ATLAS_PAGE_MAX) {
+        unsigned char *pixels = calloc(1, VD_GLYPH_ATLAS_PAGE_BYTES);
+        if (!pixels) return -1;
+        index = g_page_count++;
+        g_pages[index] = (AtlasPage){.pixels = pixels};
+    } else {
+        index = 0;
+        for (int i = 1; i < g_page_count; i++) {
+            if (g_pages[i].last_used < g_pages[index].last_used) index = i;
+        }
+        // Text already drawn from it this frame would show the new glyphs.
+        if (g_pages[index].last_used == g_frame) return -1;
+        clear_page(index);
+    }
+    g_current_page = index;
+    return page_place(&g_pages[index], width, height, x, y) ? index : -1;
+}
+
+// Returns false when the glyph has pixels but no room, so the caller retries on a later frame.
+static bool rasterise(const VdGlyphFont *font, int glyph_index, int size, VdGlyph *out)
+{
+    const stbtt_fontinfo *info = &font->info;
+    float scale = stbtt_ScaleForPixelHeight(info, (float)size);
+    int advance = 0, left_bearing = 0;
+    stbtt_GetGlyphHMetrics(info, glyph_index, &advance, &left_bearing);
+    *out = (VdGlyph){.page = -1, .advance = advance * scale};
+
+    int x0 = 0, y0 = 0, x1 = 0, y1 = 0;
+    stbtt_GetGlyphBitmapBox(info, glyph_index, scale, scale, &x0, &y0, &x1, &y1);
+    int width = x1 - x0;
+    int height = y1 - y0;
+    if (width <= 0 || height <= 0) return true;
+
+    int x = 0, y = 0;
+    int page = atlas_allocate(width, height, &x, &y);
+    unsigned char *coverage = page >= 0 ? malloc((size_t)width * (size_t)height) : NULL;
+    if (!coverage) return false;
+    stbtt_MakeGlyphBitmap(info, coverage, width, height, width, scale, scale, glyph_index);
+
+    unsigned char *pixels = g_pages[page].pixels;
+    for (int row = 0; row < height; row++) {
+        for (int col = 0; col < width; col++) {
+            unsigned char *pixel = pixels + ((size_t)(y + row) * VD_GLYPH_ATLAS_PAGE_SIZE + (size_t)(x + col)) * 4;
+            pixel[0] = pixel[1] = pixel[2] = 255;
+            pixel[3] = coverage[row * width + col];
+        }
+    }
+    free(coverage);
+
+    g_pages[page].dirty = true;
+    g_pages[page].last_used = g_frame;
+    *out = (VdGlyph){page, x, y, width, height, x0, y0, out->advance};
+    return true;
+}
+
+VdGlyph glyph_cache_get(const VdGlyphFont *font, int size, uint32_t codepoint)
+{
+    GlyphKey key;
+    memset(&key, 0, sizeof(key));
+    key.font = font;
+    key.size = size;
+    key.codepoint = codepoint;
+
+    ptrdiff_t found = hmgeti(g_glyphs, key);
+    if (found >= 0) {
+        VdGlyph glyph = g_glyphs[found].value;
+        if (glyph.page >= 0) g_pages[glyph.page].last_used = g_frame;
+        return glyph;
+    }
+
+    const VdGlyphFont *source = font;
+    int glyph_index = stbtt_FindGlyphIndex(&font->info, (int)codepoint);
+    if (glyph_index == 0 && g_fallback && g_fallback != font) {
+        int fallback_index = stbtt_FindGlyphIndex(&g_fallback->info, (int)codepoint);
+        if (fallback_index != 0) {
+            source = g_fallback;
+            glyph_index = fallback_index;
+        }
+    }
+
+    VdGlyph glyph;
+    if (rasterise(source, glyph_index, size, &glyph)) {
+        hmput(g_glyphs, key, glyph);
+        g_rasterised++;
+    }
+    return glyph;
+}
+
+void glyph_cache_begin_frame(void)
+{
+    g_frame++;
+}
+
+void glyph_cache_reset(void)
+{
+    for (int i = 0; i < g_page_count; i++) {
+        free(g_pages[i].pixels);
+    }
+    memset(g_pages, 0, sizeof(g_pages));
+    g_page_count = 0;
+    g_current_page = -1;
+    hmfree(g_glyphs);
+    g_rasterised = 0;
+}
+
+const unsigned char *glyph_cache_take_dirty_page(int page)
+{
+    if (page < 0 || page >= g_page_count || !g_pages[page].dirty) return NULL;
+    g_pages[page].dirty = false;
+    return g_pages[page].pixels;
+}
+
+VdGlyphCacheStats glyph_cache_stats(void)
+{
+    return (VdGlyphCacheStats){g_page_count, (int)hmlen(g_glyphs), g_rasterised};
+}
+
+uint32_t vd_utf8_next(const char *text, int *length)
+{
+    const unsigned char *bytes = (const unsigned char *)text;
+    *length = 1;
+    if (bytes[0] < 0x80) return bytes[0];
+
+    int count;
+    uint32_t codepoint, min;
+    if ((bytes[0] & 0xe0) == 0xc0) {
+        count = 2;
+        codepoint = bytes[0] & 0x1f;
+        min = 0x80;
+    } else if ((bytes[0] & 0xf0) == 0xe0) {
+        count = 3;
+        codepoint = bytes[0] & 0x0f;
+        min = 0x800;
+    } else if ((bytes[0] & 0xf8) == 0xf0) {
+        count = 4;
+        codepoint = bytes[0] & 0x07;
+        min = 0x10000;
+    } else {
+        return VD_UTF8_REPLACEMENT;
+    }
+
+    // A terminator is not a continuation byte, so a truncated sequence stops here.
+    for (int i = 1; i < count; i++) {
+        if ((bytes[i] & 0xc0) != 0x80) return VD_UTF8_REPLACEMENT;
+        codepoint = (codepoint << 6) | (bytes[i] & 0x3f);
+    }
+    if (codepoint < min || codepoint > 0x10ffff || (codepoint >= 0xd800 && codepoint <= 0xdfff)) {
+        return VD_UTF8_REPLACEMENT;
+    }
+    *length = count;
+    return codepoint;
+}

diff --git a/tests/glyph_cache_harness.c b/tests/glyph_cache_harness.c
new file mode 100644
index 0000000..6dfce59
--- /dev/null
+++ b/tests/glyph_cache_harness.c
@@ -0,0 +1,211 @@
+#define STB_DS_IMPLEMENTATION
+#include "stb_ds.h"
+#include "ui/glyph_cache.h"
+
+#include <math.h>
+#include <stdio.h>
+#include <string.h>
+
+// DejaVuSans-ascii.ttf is assets/fonts/DejaVuSans.ttf subset to U+0020-007E, under the same licence.
+#define FULL_FONT_PATH VD_SOURCE_DIR "/assets/fonts/DejaVuSans.ttf"
+#define ASCII_FONT_PATH VD_SOURCE_DIR "/tests/fixtures/DejaVuSans-ascii.ttf"
+
+static int failures = 0;
+
+static void expect(bool condition, const char *message)
+{
+    if (condition) return;
+    fprintf(stderr, "glyph_cache_harness: %s\n", message);
+    failures++;
+}
+
+static void expect_utf8(const char *text, uint32_t codepoint, int length, const char *message)
+{
+    int got_length = 0;
+    uint32_t got = vd_utf8_next(text, &got_length);
+    if (got == codepoint && got_length == length) return;
+    fprintf(stderr, "glyph_cache_harness: decoded U+%04X in %d bytes, want U+%04X in %d\n", (unsigned)got, got_length,
+            (unsigned)codepoint, length);
+    expect(false, message);
+}
+
+static bool same_glyph(VdGlyph a, VdGlyph b)
+{
+    return a.page == b.page && a.x == b.x && a.y == b.y && a.width == b.width && a.height == b.height &&
+           a.offset_x == b.offset_x && a.offset_y == b.offset_y && a.advance == b.advance;
+}
+
+static bool same_shape(VdGlyph a, VdGlyph b)
+{
+    return a.width == b.width && a.height == b.height && a.offset_x == b.offset_x && a.offset_y == b.offset_y &&
+           a.advance == b.advance;
+}
+
+static void test_utf8(void)
+{
+    expect_utf8("A", 'A', 1, "ASCII decodes as itself");
+    expect_utf8("\xc5\x91", 0x151, 2, "two-byte sequence decodes");
+    expect_utf8("\xe2\x82\xac", 0x20ac, 3, "three-byte sequence decodes");
+    expect_utf8("\xf0\x9f\x91\x8d", 0x1f44d, 4, "four-byte sequence decodes");
+    expect_utf8("\x80", VD_UTF8_REPLACEMENT, 1, "a lone continuation byte is replaced");
+    expect_utf8("\xc5", VD_UTF8_REPLACEMENT, 1, "a sequence cut by the terminator is replaced");
+    expect_utf8("\xe2\x82(", VD_UTF8_REPLACEMENT, 1, "a sequence cut by ASCII is replaced");
+    expect_utf8("\xc0\xaf", VD_UTF8_REPLACEMENT, 1, "an overlong sequence is replaced");
+    expect_utf8("\xed\xa0\x80", VD_UTF8_REPLACEMENT, 1, "a surrogate is replaced");
+    expect_utf8("\xf4\x90\x80\x80", VD_UTF8_REPLACEMENT, 1, "a codepoint past U+10FFFF is replaced");
+    expect_utf8("\xff", VD_UTF8_REPLACEMENT, 1, "an invalid lead byte is replaced");
+}
+
+static void test_hits_and_sizes(const VdGlyphFont *full)
+{
+    glyph_cache_reset();
+
+    VdGlyph a = glyph_cache_get(full, 30, 'A');
+    expect(a.page == 0 && a.width > 0 && a.height > 0 && a.advance > 0.0f, "a miss rasterises into the first page");
+    expect(a.offset_y < 0, "a capital sits above the baseline");
+    expect(glyph_cache_stats().rasterised == 1, "the first lookup rasterises");
+
+    VdGlyph again = glyph_cache_get(full, 30, 'A');
+    expect(same_glyph(a, again), "a hit returns the cached glyph");
+    expect(glyph_cache_stats().rasterised == 1, "a hit does not rasterise");
+
+    VdGlyph large = glyph_cache_get(full, 60, 'A');
+    expect(glyph_cache_stats().rasterised == 2, "another size is another glyph");
+    expect(!same_glyph(a, large), "sizes do not share a glyph");
+    float ratio = (float)large.height / (float)a.height;
+    expect(ratio > 1.8f && ratio < 2.2f, "a glyph at twice the size is about twice as tall");
+
+    VdGlyph space = glyph_cache_get(full, 30, ' ');
+    expect(space.page == -1 && space.advance > 0.0f, "a space advances without pixels");
+
+    const unsigned char *pixels = glyph_cache_take_dirty_page(0);
+    expect(pixels != NULL, "rasterising marks the page dirty");
+    expect(glyph_cache_take_dirty_page(0) == NULL, "taking a dirty page clears it");
+    bool covered = false;
+    for (int row = 0; pixels && row < a.height; row++) {
+        for (int col = 0; col < a.width; col++) {
+            const unsigned char *pixel =
+                pixels + ((size_t)(a.y + row) * VD_GLYPH_ATLAS_PAGE_SIZE + (size_t)(a.x + col)) * 4;
+            if (pixel[3] > 0) {
+                covered = true;
+                expect(pixel[0] == 255 && pixel[1] == 255 && pixel[2] == 255, "glyph pixels are white");
+            }
+        }
+    }
+    expect(covered, "the glyph's rect holds coverage");
+
+    VdGlyphFontMetrics metrics = glyph_font_metrics(full, 30);
+    expect(fabsf(metrics.ascent + metrics.descent - 30.0f) < 0.01f, "ascent plus descent is the Font Size");
+}
+
+static void test_fallback(const VdGlyphFont *full, const VdGlyphFont *ascii)
+{
+    glyph_cache_reset();
+    const uint32_t accented = 0x151;   // ő
+    const uint32_t ideograph = 0x65e5; // 日, in neither font
+    const uint32_t private_use = 0xe000;
+
+    glyph_cache_set_fallback(NULL);
+    VdGlyph notdef = glyph_cache_get(ascii, 30, private_use);
+    VdGlyph no_fallback = glyph_cache_get(ascii, 30, accented);
+    expect(same_shape(no_fallback, notdef), "without a fallback a missing glyph is the font's missing-glyph box");
+
+    glyph_cache_set_fallback(full);
+    VdGlyph from_full = glyph_cache_get(full, 30, accented);
+    VdGlyph fallback = glyph_cache_get(ascii, 30, 0x153); // œ
+    VdGlyph full_oe = glyph_cache_get(full, 30, 0x153);
+    expect(same_shape(fallback, full_oe), "a glyph the font lacks comes from the fallback");
+    expect(!same_shape(fallback, notdef), "a fallback glyph is not the missing-glyph box");
+    expect(from_full.advance > 0.0f, "the fallback has the accented glyph");
+
+    VdGlyph own = glyph_cache_get(ascii, 30, 'g');
+    VdGlyph full_g = glyph_cache_get(full, 30, 'g');
+    expect(same_shape(own, full_g), "a glyph the font has comes from the font");
+
+    VdGlyph neither = glyph_cache_get(ascii, 30, ideograph);
+    expect(same_shape(neither, notdef), "a glyph neither font has is the requested font's missing-glyph box");
+    VdGlyph self = glyph_cache_get(full, 30, ideograph);
+    expect(self.width > 0, "the fallback font's own missing glyph still draws a box");
+}
+
+static void test_hungarian(const VdGlyphFont *full)
+{
+    glyph_cache_reset();
+    glyph_cache_set_fallback(NULL);
+    VdGlyph notdef = glyph_cache_get(full, 22, 0x65e5);
+    const uint32_t letters[] = {0xc1, 0xe1, 0xc9, 0xe9, 0xcd, 0xed, 0xd3, 0xf3, 0xd6, 0xf6,
+                                0x150, 0x151, 0xda, 0xfa, 0xdc, 0xfc, 0x170, 0x171};
+    for (size_t i = 0; i < sizeof(letters) / sizeof(letters[0]); i++) {
+        VdGlyph glyph = glyph_cache_get(full, 22, letters[i]);
+        if (glyph.width > 0 && !same_shape(glyph, notdef)) continue;
+        fprintf(stderr, "glyph_cache_harness: U+%04X\n", (unsigned)letters[i]);
+        expect(false, "every Hungarian letter, ő and ű included, is a real glyph in the Runtime Default Font");
+    }
+}
+
+static void test_pages(const VdGlyphFont *full)
+{
+    glyph_cache_reset();
+    glyph_cache_set_fallback(NULL);
+    const int size = 300;
+
+    uint32_t first = 0;
+    uint32_t refused = 0;
+    int last_page = -1;
+    bool pages_in_order = true;
+    for (uint32_t codepoint = 0x21; codepoint < 0x250 && !refused; codepoint++) {
+        if (codepoint >= 0x7f && codepoint < 0xa1) continue;
+        int before = glyph_cache_stats().rasterised;
+        VdGlyph glyph = glyph_cache_get(full, size, codepoint);
+        if (glyph.page < 0 && glyph.advance > 0.0f && glyph_cache_stats().rasterised == before) {
+            refused = codepoint;
+            break;
+        }
+        if (!first) first = codepoint;
+        if (glyph.page < last_page || glyph.page > last_page + 1) pages_in_order = false;
+        if (glyph.page > last_page) last_page = glyph.page;
+    }
+    expect(pages_in_order, "pages fill one after another");
+    expect(glyph_cache_stats().pages == VD_GLYPH_ATLAS_PAGE_MAX, "pages grow up to the cap");
+    expect(refused != 0, "with every page used this frame, a new glyph waits for a later frame");
+    int glyphs_before = glyph_cache_stats().glyphs;
+
